/*
 * Service worker: makes the app work offline.
 * The list of files and the cache VERSION live in asset-list.js, generated by
 *   node tools/build-asset-list.mjs
 * Run it after changing any app file; a new VERSION makes installed apps show "update available".
 */
importScripts('./asset-list.js'); /* defines self.ASSET_VERSION and self.ASSETS */

const CACHE = `ganah-${self.ASSET_VERSION}`;
const IS_DEV = ['localhost', '127.0.0.1', '[::1]'].includes(self.location.hostname);

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(self.ASSETS)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('ganah-') && k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(request);
    if (res.ok) cache.put(request, res.clone());
    return res;
  } catch {
    return (await cache.match(request, { ignoreSearch: true })) ?? Response.error();
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request, { ignoreSearch: true });
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) cache.put(request, res.clone());
  return res;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    // Single-page app: every navigation gets index.html (routing is in the hash).
    event.respondWith((async () => {
      if (IS_DEV) { try { return await fetch(request); } catch { /* fall through to cache */ } }
      const cache = await caches.open(CACHE);
      return (await cache.match('./index.html')) ?? (await cache.match('./')) ?? fetch(request);
    })());
    return;
  }

  // During development always prefer fresh files; in production serve from cache.
  event.respondWith(IS_DEV ? networkFirst(request) : cacheFirst(request));
});
